import {classifyPolygon} from './geometry.mjs';
import {routePieces} from '../voyage/geometry.mjs';
const merge=intervals=>{const out=[];for(const [a,b]of intervals.sort((x,y)=>x[0]-y[0])){if(b-a<1e-12)continue;if(out.length&&a<=out.at(-1)[1]+1e-12)out.at(-1)[1]=Math.max(out.at(-1)[1],b);else out.push([a,b]);}return out;};
function cuts(rings,a,b,shift){const dx=b[0]-a[0],dy=b[1]-a[1],points=[0,1];let touched=false;for(const ring of rings)for(let i=1;i<ring.length;i++){const x=ring[i-1][0]+shift,y=ring[i-1][1],ex=ring[i][0]+shift-x,ey=ring[i][1]-y,den=dx*ey-dy*ex,qx=x-a[0],qy=y-a[1];if(Math.abs(den)<1e-14){if(Math.abs(qx*dy-qy*dx)<1e-12){const scale=dx*dx+dy*dy;if(scale){const t=(qx*dx+qy*dy)/scale,u=((x+ex-a[0])*dx+(y+ey-a[1])*dy)/scale;if(Math.max(Math.min(t,u),0)<=Math.min(Math.max(t,u),1)){points.push(Math.max(0,Math.min(1,t)),Math.max(0,Math.min(1,u)));touched=true;}}}continue;}const t=(qx*ey-qy*ex)/den,u=(qx*dy-qy*dx)/den;if(t>=-1e-12&&t<=1+1e-12&&u>=-1e-12&&u<=1+1e-12){points.push(Math.max(0,Math.min(1,t)));touched=true;}}
 const sorted=[...new Set(points.map(v=>Math.round(v*1e12)/1e12))].sort((x,y)=>x-y),inside=[];for(let i=1;i<sorted.length;i++){const lo=sorted[i-1],hi=sorted[i],t=(lo+hi)/2,relation=classifyPolygon(rings,a[0]+dx*t-shift,a[1]+dy*t);if(relation==='inside'||relation==='boundary')inside.push([lo,hi]);}return {inside,touched};}
export function routeProtectionInteractions(data,coordinates,{date=null}={}){
 if(!data)return {status:'not_loaded',areas:[],uniqueDistanceNM:null,legalNavigationDecision:false};
 const pieces=routePieces(coordinates,{maxNM:3}),byId=new Map();let unionDistance=0;
 for(const piece of pieces){const a=piece.from,b=[...piece.to];if(b[0]-a[0]>180)b[0]-=360;if(b[0]-a[0]<-180)b[0]+=360;const bx=[Math.min(a[0],b[0]),Math.min(a[1],b[1]),Math.max(a[0],b[0]),Math.max(a[1],b[1])],all=[];
  for(const f of data.features){if(f.shape.type!=='Polygon')continue;const box=f.shape.bbox;if(box[3]<bx[1]||box[1]>bx[3])continue;const local=[];let touched=false;for(const shift of [-360,0,360]){if(box[2]+shift<bx[0]||box[0]+shift>bx[2])continue;const r=cuts(f.shape.coordinates,a,b,shift);local.push(...r.inside);touched||=r.touched;}const ranges=merge(local),distance=ranges.reduce((n,[lo,hi])=>n+(hi-lo)*piece.distanceNM,0);if(distance>1e-9||touched){let row=byId.get(f.id);if(!row){const p=f.properties;row={id:f.id,siteId:f.siteId,name:p.NAME_ENG||p.NAME,designation:p.DESIG_ENG||p.DESIG,realm:p.REALM,noTake:p.NO_TAKE,distanceNM:0,boundaryIncluded:true,restrictionVerified:false,sourcePart:f.sourcePart};byId.set(f.id,row);}row.distanceNM+=distance;}all.push(...ranges);
  }unionDistance+=merge(all).reduce((n,[lo,hi])=>n+(hi-lo)*piece.distanceNM,0);
 }
 return {status:'computed_supplied_subset_only',requestedDate:date,release:data.metadata.release,areas:[...byId.values()].sort((a,b)=>b.distanceNM-a.distanceNM),uniqueDistanceNM:unionDistance,totalDistanceNM:pieces.reduce((s,p)=>s+p.distanceNM,0),pointOnlyRecords:data.features.filter(f=>f.shape.type!=='Polygon').map(f=>({id:f.id,relation:'no_boundary_no_overlap_distance'})),source:{provider:data.metadata.provider,sha256:data.metadata.archiveSha256,release:data.metadata.release,commercialDistributionCleared:false},method:'great-circle densification <=3NM; lon/lat segment-polygon clipping with holes; union intervals avoid counting overlapping designations twice',precision:'approximate geometric overlap; source uncertainty not supplied',historicalValidity:'not_encoded; database snapshot is not a voyage-date restriction',legalNavigationDecision:false,allMarineAreasCovered:false};
}
